schemas.schema-03-todos.prisma:
/// Todos created by users with titles, optional descriptions, start and due
/// dates, completion status, soft deletion status, and timestamps. Each todo
/// belongs to exactly one user represented by multi_user_todo_users. Soft
/// deletion allows trash management. Completion status is a simple boolean
/// toggle.
///
/// @namespace Todos
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model multi_user_todo_todos {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Owner user's {@link multi_user_todo_users.id}.
  multi_user_todo_user_id String @db.Uuid

  /// Title of the todo item, required field.
  title String

  /// Optional detailed description of the todo item.
  description String?

  /// Optional start date for the todo.
  start_date DateTime? @db.Timestamptz

  /// Optional due date for the todo.
  due_date DateTime? @db.Timestamptz

  /// Completion status of the todo, true means done, false means not done.
  completed Boolean

  /// Timestamp when the todo was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp of the last update to the todo.
  updated_at DateTime @db.Timestamptz

  /// Timestamp when the todo was deleted; null means not deleted (soft delete).
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  user multi_user_todo_users @relation(fields: [multi_user_todo_user_id], references: [id], onDelete: Cascade)

  editHistories multi_user_todo_todo_edit_histories[]

  @@index([multi_user_todo_user_id, completed])
  @@index([multi_user_todo_user_id, created_at])
  @@index([multi_user_todo_user_id, start_date])
  @@index([multi_user_todo_user_id, due_date])
  @@index([title(ops: raw("gin_trgm_ops"))], type: Gin)
  @@index([description(ops: raw("gin_trgm_ops"))], type: Gin)
}

/// Edit history entries for todos, capturing timestamped changes to title,
/// description, start date, and due date. Each entry references the parent
/// todo and supports soft deletion for audit trail management.
///
/// @namespace Todos
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model multi_user_todo_todo_edit_histories {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Referenced todo's {@link multi_user_todo_todos.id}.
  multi_user_todo_todo_id String @db.Uuid

  /// Changed title if updated, null if not changed.
  changed_title String?

  /// Changed description if updated, null if not changed.
  changed_description String?

  /// Changed start date if updated, null if not changed.
  changed_start_date DateTime? @db.Timestamptz

  /// Changed due date if updated, null if not changed.
  changed_due_date DateTime? @db.Timestamptz

  /// Timestamp when this edit history entry was created.
  created_at DateTime @db.Timestamptz

  /// Timestamp when this edit history entry was last updated.
  updated_at DateTime @db.Timestamptz

  /// Soft delete timestamp for this history entry.
  deleted_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  // spellchecker: ignore-next-line
  todo multi_user_todo_todos @relation(fields: [multi_user_todo_todo_id], references: [id], onDelete: Cascade, map: "multi_user_todo_todo_edit_histories_multi_user_todo_to_0d37b6e0")

  // spellchecker: ignore-next-line
  @@index([multi_user_todo_todo_id, created_at], map: "multi_user_todo_todo_edit_histories_multi_user_todo_to_e9d2e4ac")
}

