    userConnection,
    {},
  );
  typia.assert(newTodo);

  // 3. Retrieve the todo by its ID
  const retrievedTodo = await api.functional.multiUserTodo.user.todos.at(
    userConnection,
    {
      todoId: (newTodo as any).id,
